async function api(path, options = {}) {
  const headers = {'X-txtzi-Request':'1', ...options.headers};
  let body = options.body;
  if (body && !(body instanceof FormData)) {headers['Content-Type'] = 'application/json'; body = JSON.stringify(body);}
  const response = await fetch('/api' + path, {...options, headers, body, credentials:'same-origin'});
  const data = await response.json().catch(() => ({}));
  if (!response.ok) {
    const err = new Error(typeof data.detail === 'string' ? data.detail : 'Please check the form and try again.');
    err.status = response.status;
    throw err;
  }
  return data;
}
function toast(message) {clearTimeout(toastTimer); $('#toast').textContent = message; $('#toast').classList.add('visible'); toastTimer = setTimeout(() => $('#toast').classList.remove('visible'), 6000);}
function goto(route) {if (location.hash === '#' + route) render(); else location.hash = route;}
function navLink(route, name, ic, current) {return `<a href="#${route}" class="nav-link ${current === route ? 'active' : ''}">${icon(ic,16)}<span>${name}</span>${current === route ? `<span class="nav-arrow">${icon('chevron',12)}</span>` : ''}</a>`;}
