function howPage() {$('#main').innerHTML = heading('From AI draft to natural writing.','Three different models rewrite, compare and review your text.')+`<div class="how-grid">${[['1','Start with your words','Paste text or upload a document. Choose the tone and depth you want, then accept the personal-use and processing notices.'],['2','Know the price first','Check the extracted text and your fixed quote. Use your balance or make a one-time payment before starting.'],['3','Make the draft yours','For thorough editing or detector comparison, Claude maps the meaning, OpenAI writes from the outline, and Grok checks source fidelity. Compare changes and download.']].map(i=>`<div class="how-card"><span class="step-badge">${i[0]}</span><strong>${i[1]}</strong><p>${i[2]}</p></div>`).join('')}</div><div class="legal"><h2>Why three different AI models?</h2><p>Mapping meaning, writing prose and checking fidelity are different tasks. In a thorough revision, Claude first extracts a factual outline. OpenAI then writes a fresh draft from that outline. Grok compares the result with your original and proposes only specific source corrections. This is a design choice, not proof of superior accuracy or a guarantee that every error is caught.</p><h2>What happens at each pass?</h2><p>With thorough editing or detector comparison, the planner receives the source, the writer receives the content outline and protected values, and Grok receives both the source and draft. Short labels, headings and tables retain their wording. If a second revision runs, Claude and OpenAI exchange planning and writing roles; it starts from the source independently. Light editing without a detector uses sequential wording, source-comparison and final-review passes. Automated checks restore source passages when protected numbers, links or structure change. Your report lists the models and any source corrections.</p><h2>What remains your decision?</h2><p>Compare the final version with your original before using it. The models check against your source; they do not independently verify its claims. The service does not certify authorship or guarantee an AI-detector result.</p><h2>What happens to formatting?</h2><p>txtzi creates a fresh, text-focused PDF, Word document or presentation. It carries over extracted text structure where possible. Original images, charts, signatures and exact layouts are not included. Review the extracted text before paying.</p><h2>Languages</h2><p>Choose English, Hebrew, Arabic, Spanish, French or German before you request a quote. Hebrew and Arabic exports keep right-to-left paragraph alignment where the document structure supports it. The interface stays in English in this release, while your document language controls editing and export behavior.</p><h2>Can it guarantee an AI-detector pass?</h2><p>No. Optional ${esc(detectorName())} assessments describe that model’s estimates at the time of assessment. They cannot establish authorship, predict every other detector or certify that writing is human-made. When selected, txtzi measures the original, creates a three-model revision, and checks it. If the estimate is above zero, it can make one further three-model revision and recheck. It keeps the eligible version with the lowest measured score from the same detector. An unchanged original can win when hidden-format cleanup has not changed the source. If cleanup is requested, the output stays cleaned even when its estimate is higher. The report shows all attempts, including unavailable assessments.</p><h2>Our self-hosted detector</h2><p>When enabled, the txtzi detector runs the MIT-licensed Desklib model on our server. It assesses English text in overlapping sections and reports a token-weighted mean, with the model version and full-document coverage in the result. It is a beta estimate, not the percentage of AI-written words. It has not been independently validated against every current writing model or language. No detector subscription is needed for this mode.</p><h2>Hidden watermarks and document cleanup</h2><p>Fresh exports omit original author properties, comments and revision history. They rebuild the extracted text in a new file. Optional hidden-format cleanup removes byte-order marks, soft hyphens and word joiners, while preserving language joiners and bidirectional controls. The report inventories remaining format characters. These characters are not proof of AI authorship. This does not verify or remove every hidden AI watermark, statistical text signal, visible watermark or provenance mechanism. Metadata cleanup and AI-detector assessment are different features.</p><h2>What should I review?</h2><p>Always review the final wording, names, numbers, citations and any extracted text from scans. Comparing drafts with the source does not independently verify the source’s facts.</p></div>`+footer();}
function pricingPage() {$('#main').innerHTML = heading('One draft. One clear price.','Pay for what you need, when you need it.')+`<div class="account-grid"><section class="card pricing-details"><div class="eyebrow">ALL THREE ENGINES INCLUDED</div><h2>Start with a clearer draft.</h2><div class="price-big">${money(config.base_price)}<span>for up to 1,000 words</span></div><p>Then ${money(config.extra_price)} for each additional started block of 1,000 words. Every job includes three editing passes, a comparison with your original, and PDF, DOCX, PPTX and TXT downloads.</p><button class="btn btn-primary mt-20" data-action="studio">Start writing ${icon('arrow',14)}</button></section><section class="card pricing-details"><h3>Only the extras you need</h3><div class="quote-line"><span>Scanned page recognition</span><strong>${money(config.ocr_price)}/page</strong></div><div class="quote-line"><span>Presentation reconstruction</span><strong>${money(config.slide_price)}/slide</strong></div><div class="quote-line"><span>Detector comparison · up to 3 checks</span><strong>${money(config.detector_price)}/1,000 words</strong></div><div class="notice info">Your exact quote is shown before payment. No recurring subscription. Maximum 12,000 words per document.</div><p>Failed editing jobs receive an automatic credit return or card refund. If the optional detector is unavailable, its fee is returned as credits. Taxes, if applicable, appear at checkout.</p></section></div>`+footer();}
function legalPage(kind) {
  const privacy = kind === 'privacy';
  $('#main').innerHTML = `<article class="legal"><div class="eyebrow">TXTZI · PERSONAL WRITING STUDIO</div><h1>${privacy?'Your content, explained.':'A few clear expectations.'}</h1>${privacy ? `<h2>What is stored</h2><p>Your account includes your name, email, password hash, credit transactions and payment references. Extracted document text, revisions and reports are encrypted in our application database. Uploaded source files are processed temporarily and are not kept as original files.</p><h2>Who processes your writing</h2><p>When you start a paid job, the relevant text is sent to Anthropic, OpenAI and xAI for editing. The self-hosted txtzi detector processes assessments on our server. If GPTZero is configured instead, the studio names it in the processing notice and it receives text only when you select assessment. A document stays with the detector chosen at quotation; it is not silently routed to another service. Their own data handling and retention policies apply. Deleting content here does not guarantee deletion from their systems.</p><h2>Retention and deletion</h2><p>Document content is scheduled for deletion after ${Math.round((config.retention_hours||168)/24)} days. You can delete completed documents and unused quotes earlier. Jobs currently running must finish first. Deletion removes active document content; infrastructure backups may retain copies until they rotate. Payment and accounting records are retained separately.</p><h2>Payments and cookies</h2><p>Card details are entered on Stripe’s hosted checkout and are not stored by txtzi. We use an essential, HTTP-only session cookie to keep you signed in. There is no advertising tracking in this release.</p><h2>Your choices</h2><p>Review the processing notice before requesting a quote. Upload only content you have permission to share. Use the delete control in My documents to remove stored writing.</p>` : `<h2>Personal use and content rights</h2><p>You must own the uploaded content or have permission to edit it and share it with our processing providers. This service is for personal use. Do not use it for academic submission, impersonation, fraud, misleading authorship claims or to evade an obligation to disclose AI assistance.</p><h2>What you receive</h2><p>txtzi provides AI-assisted writing refinement and fresh document exports. It does not certify human authorship, guarantee a detector outcome, verify source facts or promise removal of hidden watermarks. Original images, signatures and exact formatting are not carried into text-focused exports.</p><h2>Quotes and payments</h2><p>Prices are quoted in USD, based on extracted content and your selected options. A quote is valid for 1 hour. 100 credits equal $1.00 of service value. Credits are not transferable or redeemable for cash, except where required by law. Applicable taxes are shown at checkout.</p><h2>Unsuccessful jobs</h2><p>If editing fails, the document fee is returned to the original credit balance or queued for a refund through the card provider. Bank processing times may vary. Optional detector fees are returned as credits if the assessment cannot be completed. Contact support about other billing problems.</p><h2>Your review</h2><p>You remain responsible for checking the final document and its intended use. AI may introduce errors or omit details despite multiple reviews. Preserve your own copy of the original and download any output you want to keep before the retention period ends.</p>`}${config.support_email ? `<h2>Contact</h2><p><a href="mailto:${esc(config.support_email)}">${esc(config.support_email)}</a></p>` : ''}<p class="subtle">Last updated: October 1, 2026</p></article>`+footer();
}
async function demoPage(version) {
  const response = await fetch('/static/live-example.json', {cache:'no-store'});
  if (!response.ok) throw new Error('The tested example could not be loaded. Please try again.');
  const example = await response.json();
  if (version !== routeVersion) return;
  const score = value => (value * 100).toFixed(2);
  const attemptLabels = {original:'Original',revision_1:'Revision 1',revision_2:'Revision 2'};
  const history = example.attempts?.length ? `<section class="card"><div class="card-header"><h2>All measured versions</h2></div><div class="report-section">${example.attempts.map(a=>`<div class="report-stat"><span>${esc(attemptLabels[a.version] || a.version)}${a.version===example.selected_version?' · selected':''}</span><strong>${typeof a.score==='number'?score(a.score)+' / 100':'Unavailable'}</strong></div>`).join('')}</div></section>` : '';
  const independent = example.independent_check ? `<div class="notice info"><strong>Independent research check · ${esc(example.independent_check.name)}: ${score(example.independent_check.before_score)} → ${score(example.independent_check.after_score)} / 100</strong><p>${esc(example.independent_check.notice)}</p></div>` : '';
  $('#main').innerHTML = heading('A real run. Every pass visible.','A synthetic personal-writing sample processed by the live txtzi app. No account needed to compare the result.')+`<p class="subtle"><a href="/static/research-ten-trials.html">View 10 additional research trials · experimental prompts, production unchanged</a></p><div class="notice info"><strong>txtzi detector: ${score(example.before_score)} → ${score(example.after_score)} / 100</strong><br>AI-likelihood estimate from the self-hosted English model. This is not a percentage of AI-written words, a proof of authorship or a result from another checker.</div><div class="provider-list">${example.providers.map(p=>`<div class="provider-card"><strong>${esc(p.name)}</strong><small>${esc(p.model)}</small><span class="status completed">Completed</span></div>`).join('')}</div><p class="subtle">${example.revisions} revisions · ${example.assessments} measured versions · ${esc(example.tested_at)} · ${example.elapsed_seconds} seconds</p>${history}${independent}<div class="account-grid"><section class="card"><div class="card-header"><h2>Original AI draft</h2><span class="mini-label">BEFORE</span></div><div class="source-preview">${example.original.map(t=>`<p>${esc(t)}</p>`).join('')}</div></section><section class="card"><div class="card-header"><h2>Selected output</h2><span class="mini-label">${example.selected_version==='original'?'ORIGINAL RETAINED':'AFTER'}</span></div><div class="source-preview">${example.revised.map(t=>`<p>${esc(t)}</p>`).join('')}</div></section></div><div class="notice info">${example.selected_version==='original'?'Neither rewrite scored lower, so this run retained the original text. ':''}This is one stored test example, not an accuracy benchmark. The app selects the lowest measured eligible score; if neither revision scores lower, it can retain the original. Your results will vary.</div>${example.downloads ? `<div class="action-row"><a class="btn btn-secondary" href="/static/example-original.txt" download>Download original TXT</a><a class="btn btn-secondary" href="/static/example-selected.txt" download>Download selected TXT</a></div>` : ''}<button class="btn btn-primary" data-action="studio">Try your own writing ${icon('arrow',14)}</button>`+footer();
}
async function render() {
  clearTimeout(pollTimer); const version = ++routeVersion;
  const route = location.hash.slice(1) || 'studio'; shell(route);
  $('#main').innerHTML = '<div class="loading">Opening your workspace…</div>';
  try {
    if (route === 'studio') studio();
    else if (route === 'documents') await documentsPage(version);
    else if (route.startsWith('documents/')) await documentPage(route.split('/')[1], version);
    else if (route === 'wallet') await walletPage(version);
    else if (route === 'account') accountPage();
    else if (route === 'admin') await adminPage(version);
    else if (route === 'how') howPage();
    else if (route === 'pricing') pricingPage();
    else if (['privacy','terms'].includes(route)) legalPage(route);
    else if (route === 'demo') await demoPage(version);
    else goto('studio');
  } catch (e) {if (version === routeVersion) {if (e.status===401) {user=null;needAccount();} else $('#main').innerHTML = `<div class="notice error">${esc(e.message)}</div><button class="btn btn-secondary" data-action="refresh">Try again</button>`;}}
}
function openModal(html) {modalReturnFocus = document.activeElement;$('#modal-root').innerHTML=`<div class="modal-backdrop"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title"><button class="modal-close icon-button" data-action="close-modal" aria-label="Close">${icon('close',18)}</button>${html}</section></div>`;document.body.style.overflow='hidden';setTimeout(()=>$('.modal input')?.focus(),40);}
function closeModal() {$('#modal-root').innerHTML='';document.body.style.overflow='';modalReturnFocus?.focus();}
function authModal(mode='login') {
  openModal(`<div class="brand">${brand}</div><h2 id="modal-title">${mode==='register'?'Make room for your words.':mode==='forgot'?'Let’s get you back in.':'Welcome back.'}</h2><p>${mode==='register'?'Your personal studio is one small step away.':mode==='forgot'?'We’ll email a link to reset your password.':'Your next clearer draft is waiting.'}</p><form id="auth-form" data-mode="${mode}">${mode==='register'?'<label class="form-label" for="auth-name">Your name</label><input class="form-input" id="auth-name" maxlength="80" autocomplete="name" required>':''}<label class="form-label" for="auth-email">Email address</label><input class="form-input" id="auth-email" type="email" maxlength="254" autocomplete="email" required>${mode!=='forgot'?'<label class="form-label" for="auth-password">Password</label><input class="form-input" id="auth-password" type="password" minlength="10" maxlength="128" autocomplete="'+(mode==='register'?'new-password':'current-password')+'" required>':''}${mode==='register'?'<p class="form-hint">At least 10 characters. You’ll review usage and privacy notices before processing a document.</p>':''}${mode==='register'&&new URLSearchParams(location.search).has('setup')?'<label class="form-label" for="setup-token">Administrator setup code</label><input class="form-input" id="setup-token" type="password" autocomplete="off">':''}<div class="form-error" role="alert"></div><button class="btn btn-primary btn-full" type="submit">${mode==='register'?'Create account':mode==='forgot'?'Send reset link':'Sign in'} ${icon('arrow',15)}</button></form><div class="modal-switch">${mode==='register'?'Already have a space here? <button data-action="login">Sign in</button>':'New to txtzi? <button data-action="register">Create an account</button>'}</div>${mode==='login'&&config.recovery_ready?'<div class="modal-switch"><button data-action="forgot">Forgot your password?</button></div>':''}`);
}
function handleError(e) {toast(e.message || 'Something went wrong. Please try again.');}
async function quoteAction(button) {
  saveDraft(); if (!draft.consent || !draft.provider_consent) return toast('Please accept both notices before requesting a quote.');
  if (draft.mode === 'file' && !file) return toast('Choose a document to upload first.');
  if (draft.mode === 'text' && wordCount(draft.text) < 15) return toast('Add at least 15 words to get started.');
  if (!user) {afterAuth=()=>quoteAction($('#quote-button'));authModal('register');return;}
  if (button) {button.disabled=true;button.innerHTML='<span class="spinner"></span> Reading your document…';}
  const form=new FormData();form.set('title',draft.title||file?.name?.replace(/\.[^.]+$/,'')||'Untitled document');form.set('options',JSON.stringify({...draft,detector_provider:config.detector_provider}));
  if (draft.mode==='file') form.set('file',file); else form.set('text',draft.text);
  try {const doc=await api('/documents/quote',{method:'POST',body:form});goto('documents/'+doc.id);} catch(e) {handleError(e);if(button){button.disabled=false;button.innerHTML='Get my quote '+icon('arrow',16);}}
}
async function busy(button, action) {const old=button.innerHTML;button.disabled=true;button.innerHTML='<span class="spinner"></span> One moment…';try{await action();}catch(e){handleError(e);}finally{if(button.isConnected){button.disabled=false;button.innerHTML=old;}}}
document.addEventListener('click',async e=>{
  const el=e.target.closest('[data-action]');if(!el)return;
  const action=el.dataset.action;
  if (['studio','account','demo'].includes(action)) {saveDraft();goto(action);}
  else if(action==='start-writing'){document.getElementById('writing-studio')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});$('#draft-text')?.focus({preventScroll:true});}
  else if(action==='login'||action==='register'||action==='forgot'){saveDraft();authModal(action);}
  else if(action==='close-modal')closeModal();
  else if(action==='menu')$('#sidebar').classList.toggle('open');
  else if(action==='refresh')render();
  else if(action==='mode'){saveDraft();draft.mode=el.dataset.value;studio();}
  else if(action==='tone'||action==='depth'){saveDraft();draft[action]=el.dataset.value;studio();}
  else if(action==='sample'){saveDraft();draft.text=sample+'\n\nAt the end of each week, I want to spend a few minutes looking back at what actually happened. Some tasks will have taken longer than I expected. Others might turn out to be less important than they seemed on Monday. I can use those observations to adjust the following week instead of copying the same list over and over.\n\nI also want to leave some empty space in the calendar. An unexpected call or a change of plans should not make the whole day feel like a failure. The point of keeping a plan is to give myself a useful starting point, with enough room to respond when circumstances change. Over time, I hope to notice which habits make the day easier and keep the ones that help.\n\nTo begin, I will choose one priority for the morning and put my phone away while I work on it. I do not need a complicated system or a new collection of apps. A notebook should be enough to keep track of the next step and anything I need to remember. If this approach helps, I can keep using it and make small adjustments as I learn what works.';draft.title='Making room for what matters';draft.mode='text';studio();}
  else if(action==='choose-file')$('#file-input').click();
  else if(action==='remove-file'){saveDraft();file=null;studio();}
  else if(action==='quote')quoteAction(el);
  else if(action==='generate')busy(el,async()=>{await api('/documents/'+el.dataset.id+'/generate',{method:'POST'});user=await api('/auth/me');render();});
  else if(action==='pay-document'||action==='buy-credits')busy(el,async()=>{const result=await api('/billing/checkout',{method:'POST',body:action==='pay-document'?{document_id:el.dataset.id}:{amount:Number(el.dataset.amount)}});const url=new URL(result.url);if(url.protocol!=='https:'||url.hostname!=='checkout.stripe.com')throw new Error('Checkout returned an unexpected address.');location.href=url.href;});
  else if(action==='compare'){compareMode=el.dataset.value;render();}
  else if(action==='copy'){try{await navigator.clipboard.writeText(activeDocument.revised.map(b=>b.text).join('\n\n'));toast('Refined text copied.');}catch{toast('Copy isn’t available in this browser. Download TXT instead.');}}
  else if(action==='delete'){openModal(`<h2 id="modal-title">Delete this document?</h2><p>This removes the stored original and any refined output from your active workspace. Unused paid quotes are refunded. Accounting records are retained.</p><button class="btn btn-danger btn-full" data-action="confirm-delete" data-id="${el.dataset.id}">Delete document</button><button class="btn btn-secondary btn-full" data-action="close-modal">Keep it</button>`);}
  else if(action==='confirm-delete')busy(el,async()=>{await api('/documents/'+el.dataset.id,{method:'DELETE'});closeModal();toast('Document content deleted.');goto('documents');});
  else if(action==='logout')busy(el,async()=>{await api('/auth/logout',{method:'POST'});user=null;goto('studio');});
  else if(action==='grant'){openModal(`<h2 id="modal-title">Add a little writing room.</h2><p>Grant credits to ${esc(el.dataset.name)}. This creates an audit entry.</p><form id="grant-form" data-user="${el.dataset.id}" data-key="${crypto.randomUUID()}"><label class="form-label" for="grant-amount">Amount in USD</label><input id="grant-amount" class="form-input" type="number" min="0.01" max="1000" step="0.01" required><label class="form-label" for="grant-reason">Reason</label><input id="grant-reason" class="form-input" minlength="5" maxlength="150" required><div class="form-error"></div><button class="btn btn-primary btn-full" type="submit">Grant credits</button></form>`);}
});
document.addEventListener('input',e=>{if(e.target.id==='draft-text'){draft.text=e.target.value;$('#word-count').textContent=wordCount(draft.text).toLocaleString()+' words / 12,000';$('#estimated-price').textContent=money(estimate());}});
document.addEventListener('change',e=>{if(e.target.id==='file-input')acceptFile(e.target.files[0]);else if(e.target.matches('[name]')){saveDraft();if(e.target.name==='language'&&draft.language!=='English'&&draft.detector){draft.detector=false;const check=$('[name=detector]');if(check)check.checked=false;toast('Detector scoring is English-only. Your selected language remains available for rewriting.');}if($('#estimated-price'))$('#estimated-price').textContent=money(draft.mode==='file'?config.base_price:estimate());}});
document.addEventListener('submit',async e=>{
  const form=e.target;if(!['auth-form','password-form','reset-form','grant-form'].includes(form.id))return;e.preventDefault();
  const button=$('button[type="submit"]',form),error=$('.form-error',form);error.classList.remove('visible');button.disabled=true;
  try {
    if(form.id==='auth-form'){
      const mode=form.dataset.mode;
      if(mode==='forgot'){const r=await api('/auth/forgot',{method:'POST',body:{email:$('#auth-email').value}});closeModal();toast(r.message);}
      else{user=await api('/auth/'+mode,{method:'POST',body:{email:$('#auth-email').value,password:$('#auth-password').value,name:$('#auth-name')?.value||'',bootstrap_token:$('#setup-token')?.value||''}});closeModal();await render();if(afterAuth){const f=afterAuth;afterAuth=null;f();}else toast('Your workspace is ready.');}
    }else if(form.id==='password-form'){await api('/auth/password',{method:'POST',body:{old_password:$('#old-password').value,new_password:$('#new-password').value}});form.reset();toast('Password updated. Other sessions are signed out.');}
    else if(form.id==='reset-form'){await api('/auth/reset',{method:'POST',body:{token:new URLSearchParams(location.search).get('reset'),password:$('#reset-password').value}});history.replaceState(null,'','/#studio');await render();authModal('login');toast('Password reset. Sign in with your new password.');}
    else if(form.id==='grant-form'){await api('/admin/credits',{method:'POST',body:{user_id:form.dataset.user,amount:Math.round(Number($('#grant-amount').value)*100),reason:$('#grant-reason').value,idempotency_key:form.dataset.key}});closeModal();user=await api('/auth/me');await render();toast('Credits granted and recorded.');}
  }catch(err){error.textContent=err.message;error.classList.add('visible');}finally{button.disabled=false;}
});
document.addEventListener('keydown',e=>{const modal=$('.modal');if(!modal)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const focus=[...modal.querySelectorAll('button:not(:disabled),a,input,select,textarea')];const first=focus[0],last=focus.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{saveDraft();render();window.scrollTo(0,0);});
async function init(){try{[config,user]=await Promise.all([api('/config'),api('/auth/me').catch(()=>null)]);draft.detector=Boolean(config.detector_ready);await render();if(new URLSearchParams(location.search).has('setup')&&!user)authModal('register');const checkout=new URLSearchParams(location.search).get('checkout');if(checkout==='success'){toast('Thanks. Your payment is being verified. Your balance or document will update shortly.');let attempts=0;const timer=setInterval(async()=>{if(++attempts>8){clearInterval(timer);return;}try{user=await api('/auth/me');if(['#documents','#wallet'].includes(location.hash))render();}catch{clearInterval(timer);}},4000);}else if(checkout==='cancelled')toast('Checkout was cancelled. Your quote is still in My documents.');}catch{shell('studio');$('#main').innerHTML='<div class="notice error">The studio could not connect to its server. Please refresh in a moment.</div>';}}
init();
